                    timespec="microseconds")
                lease.renewals = [MessageLeaseRenewal("R1", renewal_s)]
    replay, status = self._renew("bob", "L1", "R1")
    self.assertEqual(status, 200)
    self.assertEqual(replay, {
        "device_id": "bob", "lease_id": "L1", "renewal_id": "R1",
